(function(){
'use strict';
const E=window.EscapeEngine,T=window.EscapeTemplate,P=window.EscapePanorama;
const $=selector=>document.querySelector(selector),$$=selector=>Array.from(document.querySelectorAll(selector));
const html=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=prefix=>prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);
const clamp=(n,min,max)=>Math.min(max,Math.max(min,Number(n)||0));
const exported=!!window.ESCAPE_PACKAGE;
const hosted=!!window.ESCAPE_HOSTED,cloud=hosted?window.EscapeCloud:null,ASSET_BASE=window.ESCAPE_ASSET_BASE||'';
let project,sceneId,selectedId='',tab='scene',mode=exported?'play':'edit',run,selectedItem='',viewer=null,db=null,saveTimer,toastTimer,history=[],redo=[],savedFocus=false,drag=null,guide=true,learner='',notes='',timerHandle,pausedAt=null;
let saveState=exported?'':'Blank project · edits save automatically';
let pristineBlank='',saveQueue=Promise.resolve(),projectSwitching=false,libraryEntries=new Map();
const savedContent=new Map(),startedProjects=new Set();
function projectContent(value){const copy={...value};delete copy.updatedAt;delete copy._cloud;return JSON.stringify(copy);}
function blankProject(){const id=uid('scene');return {schemaVersion:1,id:uid('room'),title:'Untitled escape room',subtitle:'',briefing:'',learningGoals:'',debrief:'',duration:0,startSceneId:id,updatedAt:Date.now(),scenes:[{id,name:'Scene 1',description:'',background:{type:'illustration',art:'blank',data:''},view:{yaw:0,pitch:0,fov:75},objects:[]}]};}
function useProject(value,{blank=false,saved=false}={}){project=value;sceneId=value.startSceneId;selectedId='';selectedItem='';run=null;mode='edit';tab='scene';history=[];redo=[];savedFocus=false;pristineBlank=blank?projectContent(value):'';if(saved)savedContent.set(value.id,projectContent(value));saveState=blank?'Blank project · edits save automatically':cloud?(value._cloud?.unsynced?'Device draft · website save pending':'Saved on your website'):'Saved in this browser';}

let view={yaw:0,pitch:0,fov:75},viewSceneId='',viewMode='',viewProjectId='';
const scene=()=>project.scenes.find(s=>s.id===(mode==='play'?run.sceneId:sceneId))||project.scenes[0];
const selected=()=>E.find(project,selectedId);
const objectButton=(action,label,icon,cls='')=>'<button class="btn '+cls+'" data-action="'+action+'">'+T.icon(icon)+html(label)+'</button>';
const iconButton=(action,label,icon,disabled=false)=>'<button class="icon-btn" data-action="'+action+'" title="'+html(label)+'" aria-label="'+html(label)+'" '+(disabled?'disabled':'')+'>'+T.icon(icon)+'</button>';
const safeImage=source=>typeof source==='string' && (/^data:image\/(?:png|jpeg|webp|gif|svg\+xml)[;,]/i.test(source)||/^\/api\/escape-studio\?action=asset&id=asset-[a-f0-9]{64}(?:&room=[a-f0-9]{48})?$/.test(source))?source:'';
const bgSource=s=>safeImage(s.background.data)||(s.background.type==='illustration'&&s.background.art!=='blank'?ASSET_BASE+'assets/'+(['briefing','lab','command'].includes(s.background.art)?s.background.art:'briefing')+'.svg':'');
const art=o=>o.visual==='image'&&safeImage(o.image)?'<img src="'+html(o.image)+'" alt="">':T.propArt(o.visual);
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4000);}
function modal(title,body,footer=''){const el=$('#modal');el.classList.toggle('projects-modal',title==='My Projects');el.innerHTML='<div class="modal-head"><h2 id="modalTitle">'+html(title)+'</h2>'+iconButton('close-modal','Close dialog','close')+'</div><div class="modal-body">'+body+'</div>'+(footer?'<div class="modal-footer">'+footer+'</div>':'');if(!el.open)el.showModal();}
function closeModal(){const el=$('#modal');if(el.open)el.close();resumeTimer();}
function resumeTimer(){if(pausedAt!==null&&run){run.pausedMs+=(Date.now()-pausedAt);pausedAt=null;saveRun();}}
$('#modal').addEventListener('close',resumeTimer);
function field(label,value,path,type='text',help=''){return '<label class="field"><span class="field-label">'+html(label)+'</span>'+(type==='textarea'?'<textarea data-field="'+path+'">'+html(value)+'</textarea>':'<input type="'+type+'" data-field="'+path+'" value="'+html(value)+'" '+(type==='number'?'step="1"':'')+'>')+(help?'<span class="help">'+html(help)+'</span>':'')+'</label>';}
function selectField(label,value,path,options,help=''){return '<label class="field"><span class="field-label">'+html(label)+'</span><select data-field="'+path+'">'+options.map(([v,l])=>'<option value="'+html(v)+'" '+(v===value?'selected':'')+'>'+html(l)+'</option>').join('')+'</select>'+(help?'<span class="help">'+html(help)+'</span>':'')+'</label>';}
function checks(label,value,path,options,help=''){return '<div class="field"><span class="field-label">'+html(label)+'</span><div class="checklist">'+(options.length?options.map(o=>'<label><input type="checkbox" data-list="'+path+'" value="'+html(o.id)+'" '+(value.includes(o.id)?'checked':'')+'>'+html(o.name)+'</label>').join(''):'<span class="help">Add another object to connect it here.</span>')+'</div>'+(help?'<span class="help">'+html(help)+'</span>':'')+'</div>';}
function markHistory(){if(mode!=='edit')return;history.push(E.clone(project));if(history.length>20)history.shift();redo=[];updateUndoState();}
function updateUndoState(){const u=$('[data-action="undo"]'),r=$('[data-action="redo"]');if(u)u.disabled=!history.length;if(r)r.disabled=!redo.length;}
function undo(){if(!history.length)return;redo.push(E.clone(project));project=history.pop();if(!project.scenes.some(s=>s.id===sceneId))sceneId=project.scenes[0].id;if(!E.find(project,selectedId))selectedId='';scheduleSave();render();}
function redoChange(){if(!redo.length)return;history.push(E.clone(project));project=redo.pop();scheduleSave();render();}
async function openDB(){if(!window.indexedDB)return;db=await new Promise((resolve,reject)=>{const req=indexedDB.open('mayne-escape-room-studio',1);req.onupgradeneeded=()=>req.result.createObjectStore('projects',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function dbOp(operation,value){if(!db){if(operation==='getAll'){try{return JSON.parse(localStorage.getItem('escape-projects')||'[]');}catch{return [];}}const all=await dbOp('getAll');if(operation==='get')return all.find(x=>x.id===value);if(operation==='put'){const items=all.filter(x=>x.id!==value.id);items.push(value);localStorage.setItem('escape-projects',JSON.stringify(items));return;}if(operation==='delete'){localStorage.setItem('escape-projects',JSON.stringify(all.filter(x=>x.id!==value)));return;}}return new Promise((resolve,reject)=>{const tx=db.transaction('projects',operation==='put'||operation==='delete'?'readwrite':'readonly');const request=tx.objectStore('projects')[operation](value);let result;request.onsuccess=()=>{result=request.result;};tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
function scheduleSave(){if(exported)return;saveState='Saving…';updateSaveLabel();clearTimeout(saveTimer);saveTimer=setTimeout(saveProject,300);}
async function saveProject(force=false){
 clearTimeout(saveTimer);saveTimer=null;if(exported||!project)return true;
 const current=project,signature=projectContent(current);
 if(!force&&signature===pristineBlank&&!startedProjects.has(current.id)){saveState='Blank project · edits save automatically';updateSaveLabel();return true;}
 startedProjects.add(current.id);
 const snapshot=E.clone(current);
 const task=saveQueue.catch(()=>{}).then(async()=>{
  if(!force&&savedContent.get(current.id)===signature&&!(cloud&&current._cloud?.unsynced)){if(project?.id===current.id&&projectContent(project)===signature){saveState=cloud?'Saved on your website':'Saved in this browser';updateSaveLabel();}return true;}
  snapshot.updatedAt=Date.now();current.updatedAt=snapshot.updatedAt;if(cloud){current._cloud={...(current._cloud||{}),unsynced:true};snapshot._cloud={...(snapshot._cloud||{}),unsynced:true};}
  let deviceSaved=false,websiteSaved=false,failure;
  try{await dbOp('put',snapshot);deviceSaved=true;}catch(error){failure=error;}
  if(cloud){
   try{
    const meta=await cloud.save(snapshot),live=project?.id===current.id?project:current;
    live._cloud={...meta,unsynced:projectContent(live)!==signature};websiteSaved=true;
    if(!live._cloud.unsynced)try{await dbOp('put',E.clone(live));deviceSaved=true;}catch{}
   }catch(error){failure=error;}
  }
  const saved=deviceSaved||websiteSaved;
  if(saved){savedContent.set(current.id,signature);if(project?.id===current.id)pristineBlank='';}
  if(project?.id===current.id){
   saveState=projectContent(project)!==signature?'New edits waiting to save':websiteSaved?'Saved on your website':deviceSaved?(cloud?'Device draft · website save pending':'Saved in this browser'):'Save failed · export a backup';
   if(failure&&cloud)saveState=failure.status===409?'Conflict · device draft preserved':saveState;
   updateSaveLabel();
  }
  if(failure)toast(cloud?failure.message:'Browser storage is full or unavailable. Export your project to keep a backup.');
  return saved;
 });
 saveQueue=task;return task;
}
function updateSaveLabel(){const el=$('.save-indicator');if(el)el.textContent=saveState;}
function saveRun(){if(!run)return;if(window.ESCAPE_REMOTE_ROOM)window.EscapeCloud?.progress(run,learner,notes);try{sessionStorage.setItem('escape-run:'+project.id,JSON.stringify({run,learner,notes}));}catch{}}
function loadRun(){try{const saved=JSON.parse(sessionStorage.getItem('escape-run:'+project.id)||'null');if(saved?.run&&!saved.run.finished&&project.scenes.some(s=>s.id===saved.run.sceneId)){run=saved.run;learner=saved.learner||'';notes=saved.notes||'';return true;}}catch{}return false;}
function render(){viewer?.destroy();viewer=null;const scroll=$('.inspector-body')?.scrollTop||0;$('#app').innerHTML=renderHeader()+(mode==='edit'?renderEditor():renderPlayer());renderStage();const inspector=$('.inspector-body');if(inspector)inspector.scrollTop=scroll;updateTimer();}
function renderHeader(){return '<header class="header">'+(cloud?'<a class="brand" href="/facilitation.html" aria-label="Return to Classroom Tools">':'<div class="brand">')+'<div class="brand-mark">'+T.icon('logo')+'</div><div><div class="brand-title">Escape Room Studio</div><div class="brand-sub">MAYNE LEADERSHIP</div></div>'+(cloud?'</a>':'</div>')+'<div class="top-title"><strong>'+html(project.title)+'</strong><div class="save-indicator">'+html(mode==='edit'?saveState:'Player preview · '+(learner||'Learning mission'))+'</div></div><div class="header-actions">'+(mode==='edit'?objectButton('library','My Projects','folder','projects-trigger')+'<span class="top-divider hide-mobile"></span>'+iconButton('undo','Undo (Ctrl+Z)','undo',!history.length)+iconButton('redo','Redo (Ctrl+Shift+Z)','redo',!redo.length)+'<span class="top-divider"></span>'+(cloud?objectButton('publish-room','Publish','export','gold'):objectButton('help','Guide','help','hide-tablet'))+objectButton('export','Export','export','hide-mobile')+objectButton('preview','Play room','play','primary'):(!exported?objectButton('editor','Editor','left'):'')+objectButton('restart','Restart','reset','hide-mobile')+objectButton('fullscreen','Full screen','fullscreen','hide-tablet'))+'</div></header>';}
function renderEditor(){const s=scene();return '<div class="workspace"><aside class="sidebar"><div class="project-hub"><strong>Project workspace</strong><span>Save your work. Open it from My Projects.</span>'+objectButton('save-project','Save project','save','primary')+objectButton('new-blank','New blank','plus')+'</div><div class="eyebrow">Scene sequence <span>'+project.scenes.length+'</span></div><div class="scene-stack">'+project.scenes.map((sc,i)=>'<button class="scene-card '+(sc.id===sceneId?'selected':'')+'" data-scene="'+html(sc.id)+'"><div class="scene-thumb" style="background-image:url(&quot;'+html(bgSource(sc))+'&quot;)"><span class="thumb-number">'+String(i+1).padStart(2,'0')+'</span><span class="thumb-type">'+(sc.background.type==='panorama'?'360°':'Scene')+'</span></div><div class="scene-info"><div><strong>'+html(sc.name)+'</strong><small>'+sc.objects.length+' objects'+(sc.id===project.startSceneId?' · Start':'')+'</small></div>'+(sc.id===sceneId?'<i class="scene-dot"></i>':'')+'</div></button>').join('')+'</div>'+objectButton('add-scene','Add scene','plus','add-scene')+'<div class="sidebar-bottom"><strong>A room with a purpose.</strong>Connect your puzzles to what learners should think, do, and remember.'+objectButton('mission-tab','Mission settings','settings','tiny')+(cloud?'<a class="back-site" href="/facilitation.html">← Classroom Tools</a>':'')+'</div></aside><main class="main"><div class="main-heading"><div><div class="eyebrow">YOUR INTERACTIVE WORKSPACE</div><h1>'+html(s.name)+'</h1><p>Set the scene. Place your objects. Connect the clues.</p></div><div class="scene-tools">'+iconButton('duplicate-scene','Duplicate scene','copy')+iconButton('scene-up','Move scene earlier','up',project.scenes.indexOf(s)===0)+iconButton('scene-down','Move scene later','down',project.scenes.indexOf(s)===project.scenes.length-1)+'</div></div><div class="canvas-shell"><div class="canvas-bar">'+T.icon(s.background.type==='panorama'?'panorama':'photo')+'<span class="canvas-name-label">'+html(s.background.type==='panorama'?'360° canvas':'Scene canvas')+'</span><strong class="canvas-scene-name">'+html(s.name)+'</strong><span class="pill">EDIT MODE</span><span class="bar-space"></span><button data-action="guides">'+T.icon('grid')+(guide?'Hide labels':'Show labels')+'</button></div><div id="stage" class="stage editor '+(guide?'guides':'')+'"></div><div class="canvas-footer">'+T.icon('move')+'<span>Drag objects to position · Pull the corner to resize</span><span class="count">'+s.objects.length+' objects</span></div></div><div class="palette"><div class="palette-head"><strong>Add an interactive object</strong><span>Click to add · or drag onto the scene</span></div><div class="palette-grid">'+Object.entries(T.TYPE_LABELS).map(([type,label])=>'<button class="palette-item" draggable="true" data-add="'+type+'" title="'+html(label)+'">'+T.icon(type)+'<span>'+({item:'Item',code:'Lock',target:'Drop target',portal:'Doorway',decoration:'Prop'}[type]||label)+'</span></button>').join('')+'</div></div><div class="main-bottom">'+T.icon('info')+'<span>Start with a blank scene, or open a saved room from My Projects.</span><span class="shortcut"><kbd>Delete</kbd> remove · <kbd>Ctrl Z</kbd> undo</span></div></main><aside class="inspector">'+renderInspector()+'</aside></div>';}
function renderInspector(){const s=scene(),o=selected();return '<div class="inspector-tabs">'+['scene','object','mission'].map(name=>'<button data-tab="'+name+'" class="'+(tab===name?'active':'')+'">'+name[0].toUpperCase()+name.slice(1)+'</button>').join('')+'</div><div class="inspector-body">'+(tab==='mission'?missionFields():tab==='object'&&o?objectFields(o):tab==='object'?'<div class="empty-inspector">'+T.icon('target')+'<strong>Select an object on the scene</strong><br>Its appearance, clues, and puzzle rules will appear here.</div>':sceneFields(s))+'</div>';}
function sceneFields(s){return '<div class="inspector-title">'+T.icon('photo')+'<div><h2>Scene settings</h2><p>Build the environment.</p></div></div>'+objectButton('canvas-focus','Edit canvas','move','canvas-locate')+field('Scene name',s.name,'scene.name')+field('Learner instructions',s.description,'scene.description','textarea')+selectField('Environment',s.background.type,'scene.background.type',[['illustration','Illustrated room'],['photo','Photo background'],['panorama','360° photo']])+(s.background.type==='illustration'?selectField('Room design',s.background.art,'scene.background.art',[['blank','Blank canvas'],['briefing','Briefing room'],['lab','Evidence lab'],['command','Mission control']]):'<button class="upload-box" data-action="background-upload">'+T.icon(s.background.type==='panorama'?'panorama':'photo')+'<span><strong>'+(s.background.data?'Replace':'Upload')+' '+(s.background.type==='panorama'?'360° panorama':'scene photo')+'</strong><small>'+(s.background.type==='panorama'?'Full 360° equirectangular JPG / PNG, ideally 2:1.':'JPG, PNG, WebP · cropped to fill the scene.')+'</small></span></button>'+(s.background.data?objectButton('background-remove','Remove photo','trash','tiny'):'')+(s.background.type==='panorama'?'<div class="inspector-note">Drag empty space to look around. Objects stay fixed in the room. Use the view controls to zoom, then save your starting view.</div>'+objectButton('save-view','Save starting view','save','tiny'):'') )+'<div class="section-label">Objects in this scene</div><div class="object-list">'+(s.objects.length?s.objects.map(o=>'<button class="object-row" data-select="'+html(o.id)+'">'+T.icon(o.type)+'<span>'+html(o.name)+'</span><small>'+html(o.hidden?'Hidden':T.TYPE_LABELS[o.type])+'</small></button>').join(''):'<div class="empty-state">Add an object from the tray below the canvas.</div>')+'</div><div class="inspector-actions">'+objectButton('start-scene','Set as start','play','tiny')+objectButton('delete-scene','Delete scene','trash','tiny danger')+'</div>';}
function missionFields(){return '<div class="inspector-title">'+T.icon('finish')+'<div><h2>Learning mission</h2><p>The purpose behind the puzzles.</p></div></div>'+field('Room title',project.title,'project.title')+field('Short description',project.subtitle,'project.subtitle')+field('Opening briefing',project.briefing,'project.briefing','textarea')+field('Learning objectives',project.learningGoals,'project.learningGoals','textarea','One objective per line.')+field('Time limit (minutes)',project.duration,'project.duration','number','0 = untimed. Learners can continue when time runs out.')+selectField('Starting scene',project.startSceneId,'project.startSceneId',project.scenes.map(s=>[s.id,s.name]))+field('Debrief questions',project.debrief,'project.debrief','textarea','Shown after completion. One question per line.')+'<div class="inspector-note">Use clues that require the thinking you want to teach. A final decision can serve as your Finish puzzle.</div>'+objectButton('validate','Check room connections','check','tiny');}
function objectFields(o){const all=E.objects(project).filter(x=>x.id!==o.id),puzzles=all.filter(x=>['code','target','finish'].includes(x.type));return '<div class="inspector-title">'+T.icon(o.type)+'<div><h2>'+html(T.TYPE_LABELS[o.type])+'</h2><p>Appearance and interaction.</p></div></div>'+field('Object name',o.name,'object.name')+selectField('Interaction',o.type,'object.type',Object.entries(T.TYPE_LABELS))+selectField('Appearance',o.visual,'object.visual',Object.entries(T.VISUALS))+(o.visual==='image'?'<button class="upload-box" data-action="object-upload">'+T.icon('photo')+'<span><strong>'+(o.image?'Replace':'Upload')+' object image</strong><small>PNG / WebP transparency works well.</small></span></button>':'')+'<div class="fields-row">'+field('Width %',o.w,'object.w','number')+field('Height %',o.h,'object.h','number')+'</div><div class="fields-row">'+field('Rotate °',o.rotation||0,'object.rotation','number')+field('Layer',o.layer||1,'object.layer','number')+'</div><label class="checkbox-field"><input type="checkbox" data-bool="object.hidden" '+(o.hidden?'checked':'')+'>Hidden until revealed by a puzzle</label>'+(['clue','item','code','target','portal','finish'].includes(o.type)?'<div class="section-label">Clue & interaction</div>'+field(o.type==='clue'?'Clue content':'Instructions / clue',o.body,'object.body','textarea','Plain text. Clicked objects show this to learners.')+'<button class="upload-box" data-action="clue-upload">'+T.icon('photo')+'<span><strong>'+(o.clueImage?'Replace':'Add')+' clue image</strong><small>Attach a photograph, diagram, or screenshot.</small></span></button>'+(o.clueImage?objectButton('clue-remove','Remove clue image','trash','tiny'):''):'')+(['code','finish'].includes(o.type)?field('Correct answer',o.answer,'object.answer','text',o.type==='finish'?'Leave blank for a completion button.':'Numbers or words. Ignores case and extra spaces.')+field('Other accepted answers',(o.alternatives||[]).join('\n'),'object.alternatives','textarea','One equivalent answer per line.'):'')+(o.type==='target'?selectField('Accept this item',o.accepts,'object.accepts',[['','Select an item…'],...all.filter(x=>x.type==='item').map(x=>[x.id,x.name])])+selectField('After a correct drop',o.placement,'object.placement',[['consume','Use the item'],['attach','Place item on this object'],['keep','Keep item in inventory']])+ '<div class="inspector-note gold">Example: a door accepts a key. A container accepts a lid. Choose “Place item” to leave it visibly attached.</div>':'')+(['code','target','portal','finish','item'].includes(o.type)?'<div class="section-label">Connected rules</div>'+checks('Require these puzzles first',o.requires||[],'object.requires',puzzles,'All selected puzzles must be solved.')+(o.type!=='item'?checks('Reveal these objects when solved',o.reveal||[],'object.reveal',all,'Mark those objects “Hidden until revealed.”')+selectField('Then go to scene',o.destination,'object.destination',[['','Stay in current scene'],...project.scenes.map(s=>[s.id,s.name])])+field('Success message',o.success,'object.success','textarea'):''):'')+(['code','target','portal','finish'].includes(o.type)?field('Blocked / locked message',o.locked,'object.locked','textarea'):'')+(['code','target','finish'].includes(o.type)?field('Incorrect answer / item message',o.incorrect,'object.incorrect','textarea')+field('Progressive hints',(o.hints||[]).join('\n'),'object.hints','textarea','One hint per line, from gentle to explicit.'):'')+'<div class="inspector-actions">'+objectButton('duplicate-object','Duplicate','copy','tiny')+objectButton('delete-object','Delete','trash','tiny danger')+'</div>';}

function puzzles(){return E.objects(project).filter(o=>['code','target','finish'].includes(o.type));}
function renderPlayer(){const s=scene(),total=puzzles().length,completed=puzzles().filter(o=>run.solved.includes(o.id)).length;return '<div class="player-shell"><main class="player-main"><div class="player-heading"><div><h1>'+html(s.name)+'</h1><p>'+html(s.description)+'</p></div><div class="timer" id="timer">'+T.icon('clock')+'<span>20:00</span></div></div><div class="canvas-shell"><div class="canvas-bar">'+T.icon(s.background.type==='panorama'?'panorama':'photo')+'<span>'+html(project.title)+'</span><span class="bar-space"></span><span>'+(project.scenes.indexOf(s)+1)+' / '+project.scenes.length+' scenes</span></div><div id="stage" class="stage player"></div><div class="canvas-footer">'+T.icon('info')+'<span>'+(s.background.type==='panorama'?'Drag empty space to look around · ':'')+'Click objects to inspect · Drag items to use them</span></div></div><section class="inventory" aria-label="Inventory"><div class="inventory-head"><strong>Your inventory</strong><small>Drag an item, or select it then click its target</small></div><div class="inventory-items">'+(run.inventory.length?run.inventory.map(id=>E.find(project,id)).filter(Boolean).map(o=>'<button class="inventory-item '+(selectedItem===o.id?'selected-item':'')+'" data-item="'+html(o.id)+'" aria-pressed="'+(selectedItem===o.id)+'">'+art(o)+'<span>'+html(o.name)+'</span></button>').join(''):'<div class="inventory-empty">'+T.icon('folder')+'<span>Click an item in the scene to collect it.</span></div>')+'</div></section></main><aside class="player-aside"><section class="mission-card"><div class="eyebrow">YOUR MISSION</div><h2>'+html(project.title)+'</h2><p>'+html(project.briefing)+'</p><div class="progress-line"><span style="width:'+(total?completed/total*100:0)+'%"></span></div><div class="progress-meta"><span>Protocol progress</span><strong>'+completed+' / '+total+'</strong></div>'+objectButton('hints','Request a hint','hint','hint-button')+objectButton('notebook','Open notebook','notebook','notebook-button')+(run.expired?'<div class="time-expired">Time limit reached. You may keep exploring and finish the mission.</div>':'')+'</section><section class="mission-card"><div class="eyebrow">LEARNING FOCUS</div><ul>'+project.learningGoals.split('\n').filter(Boolean).map(x=>'<li>'+html(x)+'</li>').join('')+'</ul></section><div class="player-help"><strong>How to interact</strong><br>Inspect papers and controls for clues. Find objects and use them where they fit. You can also use Tab and Enter to inspect or select items.<div class="back-controls">'+objectButton('briefing','Mission briefing','info','tiny')+objectButton('run-report','Session report','export','tiny')+'</div></div></aside></div>';}
let stageObserver=null;
function layoutStage(){const stage=$('#stage');if(!stage)return;const width=stage.getBoundingClientRect().width;if(width>0){const height=Math.round(width*10/16)+'px';if(stage.style.height!==height)stage.style.height=height;}positionHotspots();}
function watchStage(stage){stageObserver?.disconnect();stageObserver=null;layoutStage();if(window.ResizeObserver){stageObserver=new ResizeObserver(layoutStage);stageObserver.observe(stage);}}
function revealCanvas(){const reveal=()=>{layoutStage();const stage=$('#stage');if(!stage)return;stage.closest('.canvas-shell')?.scrollIntoView?.({block:'nearest',inline:'nearest'});stage.focus({preventScroll:true});};if(window.requestAnimationFrame)requestAnimationFrame(reveal);else setTimeout(reveal,0);}
function selectScene(id){if(!project.scenes.some(s=>s.id===id))return;sceneId=id;selectedId='';tab='scene';render();revealCanvas();}
function renderStage(){viewer?.destroy();viewer=null;const s=scene(),stage=$('#stage');if(!stage)return;stage.dataset.sceneId=s.id;stage.setAttribute('role','region');stage.setAttribute('tabindex','-1');stage.setAttribute('aria-label',(mode==='edit'?'Editable scene canvas: ':'Room scene: ')+s.name);if(viewSceneId!==s.id||viewMode!==mode||viewProjectId!==project.id){view={...(s.view||{yaw:0,pitch:0,fov:75})};viewSceneId=s.id;viewMode=mode;viewProjectId=project.id;}stage.classList.toggle('panorama',s.background.type==='panorama');const source=bgSource(s);stage.style.backgroundImage=s.background.type==='panorama'?'none':'url("'+source.replace(/["\n\r]/g,'')+'")';let bg='';if(s.background.type==='panorama'){bg=source?'<canvas class="pano-canvas" aria-label="360-degree room view"></canvas>':'<div class="empty-panorama">'+T.icon('panorama')+'<strong>Bring your room to life</strong><span>Upload a full 360° photo in Scene settings, then drag here to look around and place clues.</span></div>';}
stage.innerHTML=bg+(mode==='edit'&&!source&&!s.objects.length?'<div class="blank-scene">'+T.icon('photo')+'<strong>Your blank scene</strong><span>Add objects below, or choose a background in Scene settings.</span></div>':'')+s.objects.filter(o=>mode==='edit'||(E.visible(run,o)&&o.type!=='decoration')|| (mode==='play'&&o.type==='decoration'&&E.visible(run,o))).map(o=>{const status=mode==='play'&&run.solved.includes(o.id);return '<button class="prop '+(mode==='edit'&&selectedId===o.id?'selected ':'')+(mode==='edit'&&o.hidden?'hidden-prop ':'')+(status?'is-solved ':'')+(mode==='play'&&!E.available(run,o)?'is-locked':'')+'" data-object="'+html(o.id)+'" data-type="'+html(o.type)+'" aria-label="'+html(o.name)+'" '+(o.type==='decoration'&&mode==='play'?'tabindex="-1" disabled':'')+' style="left:'+o.x+'%;top:'+o.y+'%;width:'+o.w+'%;height:'+o.h+'%;transform:rotate('+(o.rotation||0)+'deg);z-index:'+(o.layer||1)+'">'+art(o)+'<span class="prop-label">'+html(o.name)+'</span>'+(mode==='edit'&&selectedId===o.id?'<span class="resize-handle" data-resize="true" aria-hidden="true"></span>':'')+(status?'<span class="status-dot">✓</span>':'')+(mode==='play'&&run.placed[o.id]?'<span class="attached">'+art(E.find(project,run.placed[o.id]))+'</span>':'')+'</button>';}).join('')+(s.background.type==='panorama'?'<div class="pano-nav" aria-label="360 view controls"><button data-view="left" aria-label="Look left">'+T.icon('left')+'</button><button data-view="right" aria-label="Look right">'+T.icon('right')+'</button><button data-view="up" aria-label="Look up">'+T.icon('up')+'</button><button data-view="down" aria-label="Look down">'+T.icon('down')+'</button><span id="view-angle">0°</span><button data-view="in" aria-label="Zoom in">＋</button><button data-view="out" aria-label="Zoom out">−</button><button data-view="reset" aria-label="Reset view">'+T.icon('reset')+'</button></div>':'');
if(s.background.type==='panorama'&&source){try{viewer=new P.Viewer(stage.querySelector('canvas'),source,view,toast);}catch(error){toast(error.message);stage.style.backgroundImage='url("'+source+'")';}}
watchStage(stage);bindStage();}
function positionHotspots(){if(scene().background.type!=='panorama')return;const stage=$('#stage');if(!stage)return;const rect=stage.getBoundingClientRect();for(const el of $$('.prop')){const o=E.find(project,el.dataset.object);if(!o)continue;const pos=P.project(o.yaw||0,o.pitch||0,rect.width||800,rect.height||500,view);el.style.display=pos?'flex':'none';if(pos){el.style.left=(pos.x-o.w/2)+'%';el.style.top=(pos.y-o.h/2)+'%';}}if($('#view-angle'))$('#view-angle').textContent=Math.round(view.yaw)+'°';viewer?.draw();}
function updateTimer(){if(mode!=='play'||!run)return;const el=$('#timer');if(!el)return;const ended=run.ended||pausedAt||Date.now(),elapsed=Math.max(0,(ended-run.started-run.pausedMs)/1000);const remaining=project.duration>0?Math.max(0,project.duration*60-elapsed):elapsed;el.querySelector('span').textContent=formatTime(remaining);el.classList.toggle('warning',project.duration>0&&remaining<60);if(remaining===0&&project.duration>0&&!run.expired&&!run.finished){run.expired=true;saveRun();toast('Time limit reached. You may continue and finish the learning mission.');}}
function formatTime(seconds){const n=Math.max(0,Math.floor(seconds));return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');}
function startPreview(){closeModal();run=E.newRun(project);selectedItem='';learner='';notes='';mode='play';render();briefing(false);}
function briefing(resume=false,pause=true){if(pause)pausedAt=Date.now();modal(resume?'Resume your mission':project.title,'<p>'+html(project.subtitle)+'</p><div class="intro-meta"><span>'+project.scenes.length+' scenes</span><span>'+puzzles().length+' puzzles</span><span>'+(project.duration?project.duration+' minutes':'Untimed')+'</span></div><p>'+html(project.briefing)+'</p>'+field('Learner / team name (optional)',learner,'learner','text')+'<div class="rule-example">Inspect clues. Collect useful objects. Drag items onto their targets, or select an item and then click its target.</div>',objectButton('begin',resume?'Continue mission':'Begin mission','play','primary'));}
function handleResult(result){saveRun();if(result.ok){selectedItem='';closeModal();render();toast(result.message);if(run.finished)showCompletion();}else toast(result.message);}
function clueImage(o){return safeImage(o.clueImage)?'<img class="clue-image" src="'+html(o.clueImage)+'" alt="'+html(o.name)+' clue image">':'';}
function inspect(id){const o=E.find(project,id);if(!o||run.finished)return;if(!E.available(run,o)){toast(o.locked||'Solve the connected puzzles first.');return;}if(o.type==='decoration')return;
if(selectedItem&&o.type==='target'){handleResult(E.drop(project,run,selectedItem,id));return;}
if(o.type==='portal'||(o.type==='target'&&run.solved.includes(id))){handleResult(E.activate(project,run,id));return;}
if(o.type==='clue'){run.read=run.read||[];if(!run.read.includes(id))run.read.push(id);saveRun();modal(o.name,clueImage(o)+'<p>'+html(o.body||'No clue has been added yet.')+'</p>',objectButton('close-modal','Keep exploring','arrow'));return;}
if(o.type==='item'){modal(o.name,'<div class="big-symbol">'+art(o)+'</div>'+clueImage(o)+'<p>'+html(o.body||'This object may help you solve a puzzle.')+'</p>','<button class="btn primary" data-collect="'+html(id)+'">'+T.icon('plus')+'Collect item</button>');return;}
if((o.type==='code'||o.type==='finish')&&o.answer){if(run.solved.includes(id)){toast('This puzzle is already solved.');return;}modal(o.name,clueImage(o)+'<p>'+html(o.body||'Use the clues to work out the answer.')+'</p><form id="answerForm" data-lock="'+html(id)+'"><label class="field"><span class="field-label">Your answer</span><input id="puzzleAnswer" autocomplete="off" required placeholder="Enter your answer" aria-describedby="answerFeedback"></label><div class="modal-error" id="answerFeedback" role="status"></div></form>','<button class="btn primary" type="submit" form="answerForm">'+T.icon('code')+'Try answer</button>');setTimeout(()=>$('#puzzleAnswer')?.focus(),20);return;}
if(o.type==='finish'){modal(o.name,clueImage(o)+'<p>'+html(o.body||'Complete the mission when you are ready.')+'</p>','<button class="btn primary" data-finish="'+html(id)+'">'+T.icon('check')+'Complete mission</button>');return;}
if(o.type==='target'){modal(o.name,clueImage(o)+'<p>'+html(o.body||'Find the item that belongs here. Drag it onto this object, or select it in your inventory and click here.')+'</p>',objectButton('close-modal','Keep exploring','arrow'));}}
function hints(){const eligible=scene().objects.filter(o=>['code','target','finish'].includes(o.type)&&!run.solved.includes(o.id)&&E.visible(run,o));modal('A nudge in the right direction','<p>Hints are recorded in your session report. Reveal only as much help as you need.</p>'+eligible.map(o=>{const count=run.hints[o.id]||0;return '<div class="hint-row"><strong>'+html(o.name)+'</strong>'+(count?'<p>'+html(o.hints.slice(0,count).join('\n\n'))+'</p>':'')+(o.hints.length>count?'<button class="btn tiny gold" data-hint="'+html(o.id)+'">'+T.icon('hint')+'Reveal hint '+(count+1)+' / '+o.hints.length+'</button>':'<p>'+(o.hints.length?'All hints revealed.':'No hints have been authored for this object.')+'</p>')+'</div>';}).join('')+(eligible.length?'':'<div class="empty-state">All puzzles in this scene are complete. Look for the next doorway.</div>'),objectButton('close-modal','Return to room','arrow'));}
function notebook(){modal('Mission notebook','<p>Record the evidence, your assumptions, and what you still need to check.</p>'+field('Your notes',notes,'notes','textarea')+'<div class="section-label">Clues you inspected</div>'+((run.read||[]).length?(run.read||[]).map(id=>E.find(project,id)).filter(Boolean).map(o=>'<div class="hint-row"><strong>'+html(o.name)+'</strong><p>'+html(o.body)+'</p></div>').join(''):'<div class="empty-state">Inspected clues will be collected here.</div>'),objectButton('close-modal','Save & return','check','primary'));}
function reportBody(){const time=((run.ended||Date.now())-run.started-run.pausedMs)/1000,hintCount=Object.values(run.hints).reduce((a,b)=>a+b,0);return '<p>'+html(run.finished?'The mission is complete. Take a moment to connect the experience to your work.':'Your current learning session.')+'</p><div class="report-grid"><div><strong>'+formatTime(time)+'</strong><span>ELAPSED TIME</span></div><div><strong>'+run.attempts+'</strong><span>PUZZLE ATTEMPTS</span></div><div><strong>'+hintCount+'</strong><span>HINTS USED</span></div></div>'+(run.finished?'<div class="section-label">Discuss & reflect</div><ol>'+project.debrief.split('\n').filter(Boolean).map(q=>'<li>'+html(q)+'</li>').join('')+'</ol>':'<p>Completion status: <strong>In progress</strong></p>');}
function showCompletion(){modal('Mission accomplished','<div class="big-symbol">'+T.propArt('trophy')+'</div>'+reportBody(),objectButton('download-report','Download report','export')+objectButton('close-modal','Return to room','check','primary'));}

let suppressClickUntil=0;
function selectObject(id){selectedId=id;tab='object';for(const el of $$('.prop')){el.classList.toggle('selected',el.dataset.object===id);el.querySelector('.resize-handle')?.remove();if(el.dataset.object===id)el.insertAdjacentHTML('beforeend','<span class="resize-handle" data-resize="true" aria-hidden="true"></span>');}renderInspectorPanel();}
function renderInspectorPanel(){const el=$('.inspector');if(!el)return;const scroll=$('.inspector-body')?.scrollTop||0;el.innerHTML=renderInspector();$('.inspector-body').scrollTop=scroll;}
function bindStage(){const stage=$('#stage');stage.addEventListener('pointerdown',event=>{if(event.button!==0||event.target.closest('.pano-nav')||(mode==='play'&&run.finished))return;const el=event.target.closest('[data-object]'),rect=stage.getBoundingClientRect();
if(el&&mode==='edit'){const resizing=!!event.target.closest('[data-resize]');selectObject(el.dataset.object);markHistory();drag={kind:resizing?'resize':'move',id:el.dataset.object,start:E.clone(selected()),rect,sx:event.clientX,sy:event.clientY,moved:false,el};event.preventDefault();el.setPointerCapture?.(event.pointerId);}
else if(el&&mode==='play'&&E.find(project,el.dataset.object)?.type==='item'){drag={kind:'item',id:el.dataset.object,sx:event.clientX,sy:event.clientY,moved:false};el.setPointerCapture?.(event.pointerId);}
else if(!el&&scene().background.type==='panorama'){drag={kind:'pan',sx:event.clientX,sy:event.clientY,rect,start:{...view},moved:false};stage.setPointerCapture?.(event.pointerId);event.preventDefault();}
else if(!el&&mode==='edit'){selectedId='';tab='scene';$$('.prop').forEach(x=>{x.classList.remove('selected');x.querySelector('.resize-handle')?.remove();});renderInspectorPanel();}
});
stage.addEventListener('dragover',event=>{if(mode==='edit')event.preventDefault();});stage.addEventListener('drop',event=>{if(mode!=='edit')return;event.preventDefault();const type=event.dataTransfer.getData('application/escape-object');if(!T.TYPE_LABELS[type])return;const rect=stage.getBoundingClientRect();addObject(type,(event.clientX-rect.left)/rect.width*100,(event.clientY-rect.top)/rect.height*100);});
stage.addEventListener('wheel',event=>{if(scene().background.type!=='panorama')return;event.preventDefault();view.fov=clamp(view.fov+event.deltaY*.04,35,100);positionHotspots();},{passive:false});}
document.addEventListener('pointerdown',event=>{const el=event.target.closest('[data-item]');if(el&&mode==='play'&&!run.finished){drag={kind:'item',id:el.dataset.item,sx:event.clientX,sy:event.clientY,moved:false};el.setPointerCapture?.(event.pointerId);}});
window.addEventListener('pointermove',event=>{if(!drag)return;const dx=event.clientX-drag.sx,dy=event.clientY-drag.sy;if(Math.hypot(dx,dy)>4)drag.moved=true;if(!drag.moved)return;
if(drag.kind==='pan'){view.yaw=(drag.start.yaw-dx/drag.rect.width*drag.start.fov*drag.rect.width/drag.rect.height+540)%360-180;view.pitch=clamp(drag.start.pitch+dy/drag.rect.height*drag.start.fov,-80,80);positionHotspots();return;}
if(drag.kind==='move'||drag.kind==='resize'){const o=E.find(project,drag.id),s=drag.start;if(drag.kind==='resize'){o.w=clamp(s.w+dx/drag.rect.width*100,3,100);o.h=clamp(s.h+dy/drag.rect.height*100,3,100);drag.el.style.width=o.w+'%';drag.el.style.height=o.h+'%';if(scene().background.type!=='panorama'){o.w=Math.min(o.w,100-o.x);o.h=Math.min(o.h,100-o.y);drag.el.style.width=o.w+'%';drag.el.style.height=o.h+'%';}else positionHotspots();}else if(scene().background.type==='panorama'){const start=P.project(s.yaw,s.pitch,drag.rect.width,drag.rect.height,view);if(start){const anchor=P.directionAt(start.x/100*drag.rect.width+dx,start.y/100*drag.rect.height+dy,drag.rect.width,drag.rect.height,view);o.yaw=anchor.yaw;o.pitch=anchor.pitch;positionHotspots();}}else{o.x=clamp(s.x+dx/drag.rect.width*100,0,100-o.w);o.y=clamp(s.y+dy/drag.rect.height*100,0,100-o.h);drag.el.style.left=o.x+'%';drag.el.style.top=o.y+'%';}return;}
if(drag.kind==='item'){let ghost=$('.drag-ghost');if(!ghost){ghost=document.createElement('div');ghost.className='drag-ghost';ghost.innerHTML=art(E.find(project,drag.id));document.body.appendChild(ghost);}ghost.style.left=event.clientX+'px';ghost.style.top=event.clientY+'px';$$('.drop-hover').forEach(el=>el.classList.remove('drop-hover'));const target=document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-object]');if(target?.dataset.type==='target')target.classList.add('drop-hover');}});
window.addEventListener('pointerup',event=>{if(!drag)return;const d=drag;drag=null;$('.drag-ghost')?.remove();$$('.drop-hover').forEach(el=>el.classList.remove('drop-hover'));if(d.moved)suppressClickUntil=Date.now()+350;if(d.kind==='move'||d.kind==='resize'){if(d.moved){scheduleSave();renderInspectorPanel();}else if(history.length){history.pop();updateUndoState();}}if(d.kind==='item'&&d.moved){const target=document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-object]');if(target?.dataset.type==='target')handleResult(E.drop(project,run,d.id,target.dataset.object));else toast('Drop the item onto a target, or click it to collect it.');}});
window.addEventListener('pointercancel',()=>{drag=null;$('.drag-ghost')?.remove();$$('.drop-hover').forEach(el=>el.classList.remove('drop-hover'));});
window.addEventListener('resize',layoutStage);
document.addEventListener('dragstart',event=>{const el=event.target.closest('[data-add]');if(el)event.dataTransfer.setData('application/escape-object',el.dataset.add);else if(event.target.closest('[data-object],[data-item]'))event.preventDefault();});

function addObject(type,x=50,y=50){markHistory();const o=T.object(type,uid('object'),'New '+T.TYPE_LABELS[type].toLowerCase(),x,y);o.x=clamp(x-o.w/2,0,100-o.w);o.y=clamp(y-o.h/2,0,100-o.h);if(scene().background.type==='panorama'){const rect=$('#stage').getBoundingClientRect();const anchor=P.directionAt(x/100*rect.width,y/100*rect.height,rect.width,rect.height,view);o.yaw=anchor.yaw;o.pitch=anchor.pitch;}scene().objects.push(o);selectedId=o.id;tab='object';scheduleSave();render();}
function cleanupRefs(ids,sceneRemoved=''){for(const s of project.scenes)for(const o of s.objects){o.requires=(o.requires||[]).filter(id=>!ids.includes(id));o.reveal=(o.reveal||[]).filter(id=>!ids.includes(id));if(ids.includes(o.accepts))o.accepts='';if(o.destination===sceneRemoved)o.destination='';}}
function deleteObject(){const o=selected();if(!o)return;markHistory();scene().objects=scene().objects.filter(x=>x.id!==o.id);cleanupRefs([o.id]);selectedId='';tab='scene';scheduleSave();render();toast('Object removed. Undo restores it and its connections.');}
function duplicateObject(){const o=selected();if(!o)return;markHistory();const copy=E.clone(o);copy.id=uid('object');copy.name+=' copy';copy.x=clamp(copy.x+3,0,100-copy.w);copy.y=clamp(copy.y+3,0,100-copy.h);copy.yaw+=8;scene().objects.push(copy);selectedId=copy.id;scheduleSave();render();}
function addScene(){markHistory();const s={id:uid('scene'),name:'New scene',description:'',background:{type:'illustration',art:'blank',data:''},view:{yaw:0,pitch:0,fov:75},objects:[]};project.scenes.push(s);sceneId=s.id;selectedId='';tab='scene';scheduleSave();render();revealCanvas();}
function duplicateScene(){markHistory();const original=scene(),copy=E.clone(original),idMap={};copy.id=uid('scene');copy.name+=' copy';for(const o of copy.objects){idMap[o.id]=uid('object');o.id=idMap[o.id];}for(const o of copy.objects){o.requires=o.requires.map(id=>idMap[id]||id);o.reveal=o.reveal.map(id=>idMap[id]||id);o.accepts=idMap[o.accepts]||o.accepts;if(o.destination===original.id)o.destination=copy.id;}project.scenes.splice(project.scenes.indexOf(original)+1,0,copy);sceneId=copy.id;selectedId='';tab='scene';scheduleSave();render();}
function deleteScene(){if(project.scenes.length===1){toast('Keep at least one scene in your room.');return;}const s=scene();modal('Delete this scene?','<p>'+html(s.name)+' and its '+s.objects.length+' objects will be removed. You can restore this with Undo.</p>',objectButton('close-modal','Keep scene','left')+objectButton('confirm-delete-scene','Delete scene','trash','danger'));}
function moveScene(direction){const s=scene(),index=project.scenes.indexOf(s),next=index+direction;if(next<0||next>=project.scenes.length)return;markHistory();project.scenes.splice(index,1);project.scenes.splice(next,0,s);scheduleSave();render();}
function resolveField(path){const bits=path.split('.'),root=bits.shift();let obj=root==='project'?project:root==='scene'?scene():selected();if(!obj)return null;const key=bits.pop();for(const bit of bits)obj=obj[bit];return {obj,key};}
function setField(path,value){const target=resolveField(path);if(!target)return;const {obj,key}=target;if(['alternatives','hints'].includes(key))value=String(value).split('\n').map(x=>x.trim()).filter(Boolean);if(['duration','w','h','rotation','layer'].includes(key))value=key==='duration'?clamp(value,0,1440):key==='rotation'?clamp(value,-360,360):key==='layer'?clamp(value,1,100):clamp(value,3,100);if(['w','h'].includes(key)&&scene().background.type!=='panorama')value=Math.min(value,100-(key==='w'?obj.x:obj.y));obj[key]=value;if(path==='object.type'){if(value==='target'&&!obj.placement)obj.placement='consume';if(value==='portal')obj.visual='door';if(value==='finish')obj.visual='console';}if(path==='scene.background.type'){if(value==='panorama'){const current=scene().view||{yaw:0,pitch:0,fov:75};for(const o of scene().objects){const anchor=P.directionAt((o.x+o.w/2)/100*800,(o.y+o.h/2)/100*500,800,500,current);o.yaw=anchor.yaw;o.pitch=anchor.pitch;}}}scheduleSave();}
function refreshFieldPresentation(path){
if(path==='project.title'&&$('.top-title strong'))$('.top-title strong').textContent=project.title;
if(path==='scene.name'){if($('.main-heading h1'))$('.main-heading h1').textContent=scene().name;const label=$('.scene-card.selected strong');if(label)label.textContent=scene().name;}
if(path.startsWith('object.')){const o=selected(),el=$$('.prop').find(x=>x.dataset.object===o?.id);if(!el||!o)return;el.setAttribute('aria-label',o.name);el.querySelector('.prop-label').textContent=o.name;el.style.width=o.w+'%';el.style.height=o.h+'%';el.style.transform='rotate('+(o.rotation||0)+'deg)';el.style.zIndex=o.layer||1;if(scene().background.type==='panorama')positionHotspots();}
}
document.addEventListener('focusin',event=>{if(mode==='edit'&&event.target.dataset.field&&event.target.tagName!=='SELECT'&&!savedFocus){markHistory();savedFocus=true;}});
document.addEventListener('focusout',event=>{if(event.target.dataset.field)savedFocus=false;});
document.addEventListener('input',event=>{if(event.target.id==='projectName')event.target.setCustomValidity('');if(event.target.id==='projectSearch'){const query=event.target.value.trim().toLocaleLowerCase();let visible=0;for(const row of $$('.project-row')){row.hidden=!row.dataset.projectTitle.includes(query);if(!row.hidden)visible++;}$('#projectSearchEmpty').hidden=visible>0||!libraryEntries.size;return;}const path=event.target.dataset.field;if(path==='learner'){learner=event.target.value;saveRun();return;}if(path==='notes'){notes=event.target.value;saveRun();return;}if(path&&mode==='edit'&&event.target.tagName!=='SELECT')setField(path,event.target.value);});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.list){markHistory();const {obj,key}=resolveField(el.dataset.list);obj[key]=el.checked?[...new Set([...obj[key],el.value])]:obj[key].filter(id=>id!==el.value);scheduleSave();renderInspectorPanel();}else if(el.dataset.bool){markHistory();const {obj,key}=resolveField(el.dataset.bool);obj[key]=el.checked;scheduleSave();renderStage();}else if(el.dataset.field&&mode==='edit'){if(el.tagName==='SELECT'){markHistory();setField(el.dataset.field,el.value);render();}else{setField(el.dataset.field,el.value);refreshFieldPresentation(el.dataset.field);}}});
document.addEventListener('submit',event=>{if(event.target.id==='saveProjectForm'){event.preventDefault();confirmProjectName().catch(error=>toast(error.message));return;}if(event.target.id!=='answerForm')return;event.preventDefault();const result=E.answer(project,run,event.target.dataset.lock,$('#puzzleAnswer').value);saveRun();if(result.ok)handleResult(result);else{$('#answerFeedback').textContent=result.message;$('#puzzleAnswer').select();}});
document.addEventListener('keydown',event=>{const editing=/^(INPUT|TEXTAREA|SELECT)$/.test(event.target.tagName)||event.target.isContentEditable;if(editing||$('#modal').open)return;if(mode==='edit'&&(event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();event.shiftKey?redoChange():undo();}if(mode==='edit'&&(event.key==='Delete'||event.key==='Backspace')&&selectedId){event.preventDefault();deleteObject();}if(mode==='edit'&&selectedId&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();markHistory();const o=selected(),step=event.shiftKey?3:.5;if(scene().background.type==='panorama'){o.yaw+=(event.key==='ArrowRight'?step:event.key==='ArrowLeft'?-step:0);o.pitch+=(event.key==='ArrowUp'?step:event.key==='ArrowDown'?-step:0);}else{o.x=clamp(o.x+(event.key==='ArrowRight'?step:event.key==='ArrowLeft'?-step:0),0,100-o.w);o.y=clamp(o.y+(event.key==='ArrowDown'?step:event.key==='ArrowUp'?-step:0),0,100-o.h);}scheduleSave();renderStage();}});

function slug(){return project.title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'escape-room';}
function download(contents,name,mime){const url=URL.createObjectURL(new Blob([contents],{type:mime})),link=document.createElement('a');link.href=url;link.download=name;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function exportMenu(){modal('Export your escape room','<p>Keep an editable backup, or give learners a standalone room they can open in their browser.</p><button class="export-option" data-action="export-json">'+T.icon('save')+'<span><strong>Editable project</strong><small>All scenes, objects, rules, and uploaded images in a JSON file. Import it here to continue editing.</small></span>'+T.icon('arrow')+'</button><button class="export-option" data-action="export-player">'+T.icon('play')+'<span><strong>Standalone learner room</strong><small>One self-contained HTML file with all assets. Send it to students or upload it to your website / LMS.</small></span>'+T.icon('arrow')+'</button><button class="export-option" data-action="walkthrough">'+T.icon('notebook')+'<span><strong>Facilitator walkthrough</strong><small>Printable instructions, puzzle answers, connections, learning objectives, and debrief questions.</small></span>'+T.icon('arrow')+'</button>'+(cloud?'<button class="export-option" data-action="publish-room">'+T.icon('export')+'<span><strong>Publish & get learner link</strong><small>Save a student version on your website and copy its play link.</small></span></button><button class="export-option" data-action="cloud-reports">'+T.icon('notebook')+'<span><strong>Saved session reports</strong><small>Review student completion and export statuses.</small></span></button>':'')+'<p style="font-size:10px">'+(cloud?'Projects save on your website, with a device draft for offline work.':'Projects save in this browser.')+' Export an editable backup to move your work between computers. Learner exports run independently; session reports can be downloaded as CSV.</p>');}
async function blobData(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob);});}
async function exportPlayer(){const issues=E.validate(project);if(issues.length){showValidation(issues);return;}toast('Preparing your standalone room…');try{const copy=cloud?await cloud.embed(project):E.clone(project),files=['styles.css','engine.js','panorama.js','template.js','app.js'];const texts=await Promise.all(files.map(async file=>{const response=await fetch(ASSET_BASE+file);if(!response.ok)throw new Error('Could not read '+file);return response.text();}));await Promise.all(copy.scenes.filter(s=>s.background.type==='illustration'&&s.background.art!=='blank'&&!s.background.data).map(async s=>{const response=await fetch(bgSource(s));if(!response.ok)throw new Error('Could not embed a room background.');s.background.data=await blobData(await response.blob());}));const json=JSON.stringify(copy).replace(/</g,'\\u003c');const content='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html(copy.title)+'</title><style>'+texts[0]+'</style></head><body><div id="app"></div><dialog id="modal" aria-labelledby="modalTitle"></dialog><div id="toast" role="status" aria-live="polite"></div><input id="fileInput" type="file" hidden><script>window.ESCAPE_PACKAGE='+json+';<\/script>'+texts.slice(1).map(js=>'<script>'+js.replace(/<\/script/gi,'<\\/script')+'<\/script>').join('')+'</body></html>';download(content,slug()+'-play.html','text/html');closeModal();toast('Learner room exported. Open the HTML file in a browser to play.');}catch(error){toast('Export failed: '+error.message);}}
function downloadReport(){const rows=[['Room','Learner / team','Completion','Time seconds','Puzzle attempts','Hints used','Event','Object','Event time seconds','Notes']];const base=[project.title,learner,run.finished?'Complete':'In progress',Math.max(0,Math.round(((run.ended||Date.now())-run.started-run.pausedMs)/1000)),run.attempts,Object.values(run.hints).reduce((a,b)=>a+b,0)];if(run.log.length)run.log.forEach((entry,i)=>rows.push([...base,entry.event,entry.name,Math.max(0,Math.round(entry.elapsed/1000)),i===0?notes:'']));else rows.push([...base,'','',0,notes]);const csv=rows.map(row=>row.map(cell=>'"'+String(cell??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');download('\ufeff'+csv,slug()+'-session.csv','text/csv;charset=utf-8');toast('Session report downloaded.');}
function walkthrough(){const name=id=>E.find(project,id)?.name||id;const content='<!doctype html><html lang="en"><head><meta charset="utf-8"><title>'+html(project.title)+' · Facilitator guide</title><style>body{font:15px/1.75 system-ui,sans-serif;color:#233c50;max-width:850px;padding:35px;margin:auto}h1{color:#245c89}h2{border-bottom:1px solid #d7e2eb;padding-bottom:8px;margin-top:30px}article{border:1px solid #d7e2eb;border-radius:8px;padding:16px 20px;margin:14px 0;break-inside:avoid}p{white-space:pre-line}small{color:#678195}.rule{background:#f2f6fa;padding:12px}button{background:#245c89;color:white;padding:10px 17px;border:0;border-radius:5px;cursor:pointer}@media print{button{display:none}body{padding:0}}</style></head><body><button onclick="print()">Print / save as PDF</button><h1>'+html(project.title)+'</h1><p>'+html(project.subtitle)+'</p><p><strong>Time:</strong> '+(project.duration?project.duration+' minutes':'Untimed')+' · <strong>Start:</strong> '+html(project.scenes.find(s=>s.id===project.startSceneId)?.name)+'</p><h2>Briefing</h2><p>'+html(project.briefing)+'</p><h2>Learning objectives</h2><p>'+html(project.learningGoals)+'</p>'+project.scenes.map((s,i)=>'<h2>'+String(i+1)+'. '+html(s.name)+'</h2><p>'+html(s.description)+'</p>'+s.objects.filter(o=>o.type!=='decoration').map(o=>'<article><strong>'+html(o.name)+'</strong> <small>'+html(T.TYPE_LABELS[o.type])+(o.hidden?' · Initially hidden':'')+'</small><p>'+html(o.body)+'</p><div class="rule">'+(o.answer?'<strong>Answer:</strong> '+html([o.answer,...o.alternatives].join(' / '))+'<br>':'')+(o.accepts?'<strong>Accepts:</strong> '+html(name(o.accepts))+' · '+html(o.placement)+'<br>':'')+(o.requires.length?'<strong>Requires:</strong> '+html(o.requires.map(name).join(', '))+'<br>':'')+(o.reveal.length?'<strong>Reveals:</strong> '+html(o.reveal.map(name).join(', '))+'<br>':'')+(o.destination?'<strong>Destination:</strong> '+html(project.scenes.find(s=>s.id===o.destination)?.name)+'<br>':'')+'<strong>Success:</strong> '+html(o.success)+'</div>'+(o.hints.length?'<p><strong>Progressive hints:</strong>\n'+html(o.hints.map((h,i)=>(i+1)+'. '+h).join('\n'))+'</p>':'')+'</article>').join('')).join('')+'<h2>Debrief</h2><p>'+html(project.debrief)+'</p></body></html>';download(content,slug()+'-facilitator-guide.html','text/html');toast('Facilitator guide exported.');}
function showValidation(issues=E.validate(project)){modal('Room connection check',issues.length?'<p>Resolve these connections before exporting a learner room.</p><ul class="validation-list">'+issues.map(x=>'<li>'+html(x)+'</li>').join('')+'</ul>':'<div class="big-symbol">'+T.icon('check')+'</div><p><strong>Your connections are valid.</strong> A starting scene and finish object are present, and all item and object references exist.</p><p>Play the room to confirm the clues provide a solvable route for your learners.</p>',objectButton('close-modal','Back to editor','left'));}
function normalizeImported(value){if(!value||value.schemaVersion!==1||!Array.isArray(value.scenes)||!value.scenes.length||value.scenes.length>100)throw new Error('Choose an Escape Room Studio project JSON file.');const copy=E.clone(value);for(const key of ['title','subtitle','briefing','learningGoals','debrief'])copy[key]=String(copy[key]||'');copy.duration=clamp(copy.duration,0,1440);copy.id=uid('room');delete copy._cloud;copy.updatedAt=Date.now();for(const s of copy.scenes){if(!s.id||!Array.isArray(s.objects)||s.objects.length>300)throw new Error('Scene data is invalid.');s.name=String(s.name||'Untitled scene');s.description=String(s.description||'');s.background=s.background||{type:'illustration',art:'briefing',data:''};if(!['illustration','photo','panorama'].includes(s.background.type))s.background.type='illustration';s.background.data=safeImage(s.background.data);s.view=s.view||{yaw:0,pitch:0,fov:75};for(let i=0;i<s.objects.length;i++){const input=s.objects[i];if(!input.id||!T.TYPE_LABELS[input.type])throw new Error('An object has an invalid interaction.');const o={...T.object(input.type,input.id,String(input.name||'Object'),0,0),...input};s.objects[i]=o;for(const key of ['name','body','answer','success','incorrect','locked'])o[key]=String(o[key]||'');for(const key of ['requires','reveal','hints','alternatives'])o[key]=Array.isArray(o[key])?o[key].map(String):[];o.w=clamp(o.w,3,100);o.h=clamp(o.h,3,100);o.x=clamp(o.x,0,100-o.w);o.y=clamp(o.y,0,100-o.h);o.yaw=clamp(o.yaw,-360,360);o.pitch=clamp(o.pitch,-85,85);o.rotation=clamp(o.rotation,-360,360);o.image=safeImage(o.image);o.clueImage=safeImage(o.clueImage);}}if(new Set(copy.scenes.map(s=>s.id)).size!==copy.scenes.length||new Set(E.objects(copy).map(o=>o.id)).size!==E.objects(copy).length)throw new Error('Scene or object IDs are duplicated.');if(!copy.scenes.some(s=>s.id===copy.startSceneId))copy.startSceneId=copy.scenes[0].id;return copy;}
function chooseFile(kind){const input=$('#fileInput');input.value='';input.accept=kind==='project'?'.json,application/json':'image/jpeg,image/png,image/webp,image/gif';const targetScene=sceneId,targetObject=selectedId;input.onchange=async()=>{const file=input.files[0];if(!file)return;try{if(file.size>32*1024*1024)throw new Error('Choose a file smaller than 32 MB.');if(kind==='project'){const imported=normalizeImported(JSON.parse(await file.text()));clearTimeout(saveTimer);if(!await saveProject())throw new Error('Export your current edits before importing another project.');project=imported;pristineBlank='';sceneId=project.startSceneId;selectedId='';history=[];redo=[];tab='scene';await saveProject();closeModal();render();toast('Project imported. You can edit every scene and object.');return;}if(!/^image\/(jpeg|png|webp|gif)$/.test(file.type))throw new Error('Choose a JPG, PNG, WebP, or GIF image.');const data=await blobData(file),img=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(new Error('The image could not be decoded.'));image.src=data;});const s=project.scenes.find(x=>x.id===targetScene);if(!s)return;const max=kind==='background'&&s.background.type==='panorama'?4096:2048;let result=data;if(img.width>max||img.height>max){const ratio=Math.min(max/img.width,max/img.height),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*ratio);canvas.height=Math.round(img.height*ratio);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);result=canvas.toDataURL(kind==='background'?'image/jpeg':'image/png',.9);}markHistory();if(kind==='background')s.background.data=result;else{const o=E.find(project,targetObject);if(!o)return;if(kind==='clue'){o.clueImage=result;}else{o.visual='image';o.image=result;}}scheduleSave();render();toast(kind==='background'&&s.background.type==='panorama'&&Math.abs(img.width/img.height-2)>.2?'Photo added. Full 360° panoramas work best at a 2:1 ratio.':'Image added.');}catch(error){toast(error.message||'This file could not be opened.');}};input.click();}
function projectDate(value){const date=new Date(value.updated_at||value.updatedAt);return Number.isNaN(date.getTime())?'Date unavailable':date.toLocaleString(undefined,{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'});}
async function library(){
 clearTimeout(saveTimer);await saveProject();let local=[],remote=[],notice='';
 try{local=await dbOp('getAll');}catch{notice='Device backups could not be read.';}
 if(cloud)try{remote=await cloud.list();}catch(error){notice='Website projects are temporarily unavailable. Your device drafts are shown below.';toast(error.message);}
 libraryEntries=new Map(remote.map(p=>[p.id,{...p,source:'website'}]));
 for(const p of local)if(!libraryEntries.has(p.id)||p._cloud?.unsynced)libraryEntries.set(p.id,{...p,source:'device'});
 const items=[...libraryEntries.values()].sort((a,b)=>new Date(b.updated_at||b.updatedAt)-new Date(a.updated_at||a.updatedAt));
 const rows=items.map(p=>{const count=typeof p.scenes==='number'?p.scenes:p.scenes.length,pending=cloud&&p.source==='device';return '<article class="project-row" data-project-title="'+html(p.title.toLocaleLowerCase())+'"><div class="project-symbol">'+T.icon('folder')+'</div><div class="project-details"><strong>'+html(p.title)+'</strong><span class="project-badge">'+(pending?'Device draft · sync pending':p.published?'Published · editable draft':'In progress')+'</span><small>'+count+' scene'+(count===1?'':'s')+' · Last edited '+html(projectDate(p))+(p.id===project.id?' · Current project':'')+'</small></div><button class="btn project-open" data-open-project="'+html(p.id)+'" aria-label="Open '+html(p.title)+'">'+T.icon('folder')+'Open</button></article>';}).join('');
 modal('My Projects','<div class="projects-intro"><div><strong>Your projects in progress</strong><p>'+(cloud?'Save your rooms here and reopen them whenever you want to keep building. Website projects are available from your other computers.':'Save your rooms here and reopen them whenever you want to keep building. Projects are stored in this browser; export a backup to move them to another computer.')+'</p></div><span class="project-total">'+items.length+' saved</span></div>'+(notice?'<p class="projects-notice" role="status">'+html(notice)+'</p>':'')+'<label class="project-search">'+T.icon('folder')+'<input id="projectSearch" type="search" placeholder="Search projects by name" aria-label="Search projects by name"></label><div class="project-list">'+(rows||'<div class="projects-empty">'+T.icon('folder')+'<strong>No saved projects yet</strong><p>Add content to your blank project, or choose Save project to give it a name. It will appear here.</p></div>')+'</div><p id="projectSearchEmpty" class="empty-state" hidden>No projects match your search.</p><p class="projects-footnote">The studio always opens with a blank project. Open a saved project here to continue editing it.</p>',objectButton('import','Import project','folder')+objectButton('new-template','Use example','play')+objectButton('new-blank','New blank project','plus','primary'));
}
async function openProject(id){
 if(projectSwitching)return;projectSwitching=true;
 try{
  if(!await saveProject()){toast('Your current edits could not be saved. Export a backup before opening another project.');return;}
  const entry=libraryEntries.get(id);let value;
  if(cloud&&entry?.source==='website'){
   try{value=await cloud.get(id);}catch(error){value=await dbOp('get',id);if(!value)throw error;toast('Opened the device backup. Website saving will retry when you edit.');value._cloud={...(value._cloud||{}),unsynced:true};}
  }else value=await dbOp('get',id);
  if(!value)throw new Error('This project is unavailable. Reopen My Projects and try again.');
  useProject(value,{saved:true});try{await dbOp('put',E.clone(value));}catch{saveState+=' · device backup unavailable';}
  closeModal();render();
 }catch(error){toast(error.message||'This project could not be opened. Your current project is still open.');}
 finally{projectSwitching=false;}
}
async function newProject(blank){
 if(projectSwitching)return;projectSwitching=true;
 try{
  if(!await saveProject()){toast('Your current edits could not be saved. Export a backup before starting another project.');return;}
  const value=blank?blankProject():T.template();value.id=uid('room');useProject(value,{blank});
  closeModal();render();if(!blank)await saveProject();
 }finally{projectSwitching=false;}
}
function nameProject(){modal('Save project','<p>Give your escape room a name so you can find it in My Projects. Your edits save automatically as you work.</p><form id="saveProjectForm"><label class="field"><span class="field-label">Project name</span><input id="projectName" required maxlength="200" value="'+html(project.title)+'" autocomplete="off"></label></form>',objectButton('close-modal','Cancel','close')+'<button class="btn primary" type="submit" form="saveProjectForm">'+T.icon('save')+'Save project</button>');setTimeout(()=>{$('#projectName')?.focus();$('#projectName')?.select();},0);}
async function confirmProjectName(){const name=$('#projectName').value.trim();if(!name){$('#projectName').setCustomValidity('Enter a project name.');$('#projectName').reportValidity();return;}markHistory();project.title=name;if(await saveProject(true)){closeModal();render();toast(cloud&&project._cloud?.unsynced?'Project kept on this device. Website saving will retry.':'Project saved. Find it in My Projects.');}}
function help(){modal('Build a room that teaches','<ol class="help-list"><li><strong>Set the mission.</strong> Use Mission settings for your briefing, learning objectives, time limit, and debrief.</li><li><strong>Create scenes.</strong> Use an illustrated room, upload a normal photo, or choose 360° photo and upload a full equirectangular panorama.</li><li><strong>Place objects.</strong> Click an object in the tray or drag it onto the scene. Drag to move, and pull the blue corner to resize. Arrow keys nudge selected objects.</li><li><strong>Add clues.</strong> Select an object and edit its clue text. Use an uploaded transparent image for a custom object.</li><li><strong>Connect puzzles.</strong> A Lock accepts a number or word. A Drop target accepts a specific Item. A Doorway takes learners to another scene.</li><li><strong>Build a sequence.</strong> Require earlier puzzles, reveal hidden objects, and choose the next scene after success.</li><li><strong>Add a Finish object.</strong> It completes the mission and displays your debrief. It may require an answer and earlier puzzles.</li><li><strong>Test and share.</strong> Play the full room, then export an editable backup and a standalone learner HTML file.</li></ol><div class="rule-example"><strong>Key + door:</strong> Add an Item with a key appearance. Add a Drop target with a door appearance. Select the key under “Accept this item,” then choose the next scene.<br><br><strong>Lid + container:</strong> Add a lid Item and a container Drop target. Accept the lid and choose “Place item on this object.” Reveal a hidden clue when solved.</div>',objectButton('close-modal','Start building','arrow','primary'));}


function roomURL(){return location.origin+'/escape-room-play.html?room='+project._cloud.token;}
function showRoomLink(){
 const link=roomURL();
 modal('Your learner room is published','<p>Students can open this link without entering your website PIN. It loads the version you published; your next edits remain a draft until you publish again.</p><label class="field"><span class="field-label">Learner link</span><input id="roomShareLink" readonly value="'+html(link)+'"></label><p><strong>Published draft version:</strong> '+html(project._cloud.publishedVersion||project._cloud.version)+'</p><p>Each learner or team plays an independent session. Completion, attempts, hints, and notes are saved to your room reports.</p><a class="btn" href="'+html(link)+'" target="_blank" rel="noopener">'+T.icon('play')+'Open learner room</a>',objectButton('unpublish-room','Unpublish','close')+objectButton('cloud-reports','Reports','notebook')+objectButton('copy-room-link','Copy learner link','copy','primary'));
}
async function publishRoom(){
 const issues=E.validate(project);if(issues.length){showValidation(issues);return;}
 clearTimeout(saveTimer);if(!await saveProject()||project._cloud?.unsynced){toast('Save the latest draft on your website before publishing. Your device draft is preserved.');return;}
 try{const meta=await cloud.publish(project);project._cloud={...meta,unsynced:false};await dbOp('put',E.clone(project));showRoomLink();}catch(error){toast(error.message);}
}
async function copyRoomLink(){
 const input=$('#roomShareLink');input?.select();
 try{await navigator.clipboard.writeText(roomURL());toast('Learner link copied.');}catch{toast('Select the learner link and copy it.');}
}
async function unpublishRoom(){
 try{project._cloud={...(await cloud.unpublish(project)),unsynced:false};await dbOp('put',E.clone(project));closeModal();toast('Learner access is closed. Your editable room is retained.');}catch(error){toast(error.message);}
}
let recentReports=[];
async function cloudReports(){
 try{recentReports=await cloud.reports(project.id);modal('Room session reports','<p>Sessions for '+html(project.title)+'. Reports record learning activity reported by the student player.</p>'+(recentReports.length?'<div class="report-table"><table><thead><tr><th>Learner / team</th><th>Status</th><th>Time</th><th>Hints</th></tr></thead><tbody>'+recentReports.map(r=>'<tr><td>'+html(r.learner||'Unnamed learner')+'</td><td>'+html(r.finished?'Complete':'In progress')+'</td><td>'+formatTime(r.elapsed)+'</td><td>'+r.hints+'</td></tr>').join('')+'</tbody></table></div>':'<div class="empty-state">Student sessions will appear here after they start a published room.</div>'),objectButton('close-modal','Close','close')+objectButton('cloud-reports-csv','Export completion CSV','export','primary'));}catch(error){toast(error.message);}
}
async function cloudReportsCSV(){
 const rows=[['Room','Learner / team','Completion','Time seconds','Attempts','Hints','Published version','Started','Completed','Notes'],...recentReports.map(r=>[project.title,r.learner,r.finished?'Complete':'In progress',r.elapsed,r.attempts,r.hints,r.publication_version,r.started_at,r.completed_at||'',r.notes||''])];
 const csv=rows.map(row=>row.map(cell=>'"'+String(cell??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');download('\ufeff'+csv,slug()+'-completion-statuses.csv','text/csv;charset=utf-8');
}
document.addEventListener('click',async event=>{if(Date.now()<suppressClickUntil)return;const el=event.target.closest('button');if(!el)return;
if(el.dataset.scene){selectScene(el.dataset.scene);return;}
if(el.dataset.tab){tab=el.dataset.tab;renderInspectorPanel();return;}
if(el.dataset.select){selectObject(el.dataset.select);return;}
if(el.dataset.add){addObject(el.dataset.add);return;}
if(el.dataset.object){mode==='edit'?selectObject(el.dataset.object):inspect(el.dataset.object);return;}
if(el.dataset.item){selectedItem=selectedItem===el.dataset.item?'':el.dataset.item;render();if(selectedItem)toast(E.find(project,selectedItem).name+' selected. Click the target to use it.');return;}
if(el.dataset.collect){handleResult(E.collect(project,run,el.dataset.collect));return;}
if(el.dataset.finish){handleResult(E.activate(project,run,el.dataset.finish));return;}
if(el.dataset.hint){const id=el.dataset.hint;run.hints[id]=(run.hints[id]||0)+1;saveRun();hints();return;}
if(el.dataset.openProject){await openProject(el.dataset.openProject);return;}
if(el.dataset.view){const action=el.dataset.view;if(action==='reset')Object.assign(view,scene().view);else if(action==='left')view.yaw-=15;else if(action==='right')view.yaw+=15;else if(action==='up')view.pitch=clamp(view.pitch+10,-80,80);else if(action==='down')view.pitch=clamp(view.pitch-10,-80,80);else if(action==='in')view.fov=clamp(view.fov-10,35,100);else if(action==='out')view.fov=clamp(view.fov+10,35,100);positionHotspots();return;}
const action=el.dataset.action;switch(action){
case 'close-modal':closeModal();break;
case 'help':help();break;
case 'undo':undo();break;
case 'redo':redoChange();break;
case 'guides':guide=!guide;render();break;
case 'mission-tab':tab='mission';renderInspectorPanel();break;
case 'add-scene':addScene();break;
case 'duplicate-scene':duplicateScene();break;
case 'delete-scene':deleteScene();break;
case 'confirm-delete-scene':{markHistory();const s=scene();project.scenes=project.scenes.filter(x=>x.id!==s.id);cleanupRefs(s.objects.map(o=>o.id),s.id);sceneId=project.scenes[0].id;if(project.startSceneId===s.id)project.startSceneId=sceneId;selectedId='';tab='scene';closeModal();scheduleSave();render();break;}
case 'scene-up':moveScene(-1);break;
case 'scene-down':moveScene(1);break;
case 'start-scene':markHistory();project.startSceneId=sceneId;scheduleSave();render();toast('This scene is now the start of the mission.');break;
case 'duplicate-object':duplicateObject();break;
case 'delete-object':deleteObject();break;
case 'canvas-focus':revealCanvas();break;
case 'background-upload':chooseFile('background');break;
case 'object-upload':chooseFile('object');break;
case 'clue-upload':chooseFile('clue');break;
case 'clue-remove':markHistory();selected().clueImage='';scheduleSave();renderInspectorPanel();break;
case 'background-remove':markHistory();scene().background.data='';scheduleSave();render();break;
case 'save-view':markHistory();scene().view={...view};scheduleSave();toast('Starting view saved.');break;
case 'validate':showValidation();break;
case 'preview':await saveProject();startPreview();break;
case 'editor':closeModal();saveRun();mode='edit';sceneId=run.sceneId;selectedId='';tab='scene';render();break;
case 'begin':closeModal();saveRun();render();break;
case 'briefing':briefing(true,false);break;
case 'restart':modal('Restart this mission?','<p>Your current puzzle progress, inventory, and notes will reset.</p>',objectButton('close-modal','Keep playing','left')+objectButton('confirm-restart','Restart mission','reset','primary'));break;
case 'confirm-restart':startPreview();break;
case 'hints':hints();break;
case 'notebook':notebook();break;
case 'run-report':modal(run.finished?'Mission report':'Session report',reportBody(),objectButton('download-report','Download CSV','export','primary'));break;
case 'download-report':downloadReport();break;
case 'fullscreen':if(document.fullscreenElement){await document.exitFullscreen?.();}else{try{await document.documentElement.requestFullscreen?.();}catch{toast('Full-screen mode is not available in this browser.');}}break;
case 'export':exportMenu();break;
case 'export-json':download(JSON.stringify(cloud?await cloud.embed(project):project,null,2),slug()+'-project.json','application/json');toast('Editable project exported.');break;
case 'export-player':await exportPlayer();break;
case 'walkthrough':walkthrough();break;
case 'publish-room':await publishRoom();break;
case 'copy-room-link':await copyRoomLink();break;
case 'unpublish-room':await unpublishRoom();break;
case 'cloud-reports':await cloudReports();break;
case 'cloud-reports-csv':await cloudReportsCSV();break;
case 'library':await library();break;
case 'save-project':nameProject();break;
case 'import':chooseFile('project');break;
case 'new-blank':await newProject(true);break;
case 'new-template':await newProject(false);break;
}});

async function initialize(){
 if(exported){project=window.ESCAPE_PACKAGE;sceneId=project.startSceneId;const resume=loadRun();if(!resume)run=E.newRun(project);render();briefing(resume);}
 else{try{await openDB();}catch{toast('Device storage is unavailable. Export backups to keep your work.');}useProject(blankProject(),{blank:true});render();}
 timerHandle=setInterval(updateTimer,1000);
}
initialize().catch(error=>{$('#app').innerHTML='<main style="padding:40px"><h1>Escape Room Studio</h1><p>The room could not load: '+html(error.message)+'</p><button class="btn" onclick="location.reload()">Reload</button></main>';});
window.addEventListener('beforeunload',()=>{saveRun();window.EscapeCloud?.beacon();if(!exported&&saveTimer)saveProject();});
})();
